const s=input.state,e=input.event;
if(e.type!=='action')return {state:s};
const a=e.actionId;
const pad=n=>String(n).padStart(2,'0');
const fmt=ts=>{const d=new Date(ts);return pad(d.getHours())+':'+pad(d.getMinutes())+':'+pad(d.getSeconds());};
const kindNames={quiz:'Викторина',puzzle:'Пазл',hint:'Подсказка'};
const deltas={quiz:3,puzzle:2,hint:-5};
if(a==='teamPicker'){
 const v=Number(e.value);
 if(v===1||v===2){s.selectedTeam=v;s.message='';}
} else if(a==='undo'){
 if(s.history.length>0){
  const last=s.history[s.history.length-1];
  if(last.team==='mel'){s.mel=s.mel-last.delta;}else{s.yantar=s.yantar-last.delta;}
  s.history=s.history.slice(0,s.history.length-1);
  const rest=last.team==='mel'?s.mel:s.yantar;
  s.message='Отменено: «'+last.teamName+'», '+last.kind+'. Баланс: '+rest+' очк.';
 }
 s.canUndo=s.history.length>0;
} else if(a==='quiz'||a==='puzzle'||a==='hint'){
 const team=s.selectedTeam===2?'mel':'yantar';
 const teamName=s.selectedTeam===2?'Мел':'Янтарь';
 const delta=deltas[a];
 const current=team==='mel'?s.mel:s.yantar;
 if(a==='hint'&&current<5){
  s.message='Нельзя взять подсказку в долг: у команды «'+teamName+'» только '+current+' очк. Нужно 5.';
 } else {
  const next=current+delta;
  if(team==='mel'){s.mel=next;}else{s.yantar=next;}
  s.seq=s.seq+1;
  const rec={id:'h'+s.seq,team:team,teamName:teamName,kind:kindNames[a],delta:delta,deltaLabel:(delta>0?'+':'−')+Math.abs(delta),balance:next,time:fmt(Date.now())};
  s.history=s.history.concat([rec]);
  if(s.history.length>100){s.history=s.history.slice(s.history.length-100);}
  s.message='«'+teamName+'»: '+rec.deltaLabel+' за '+kindNames[a].toLowerCase()+'. Баланс: '+next+' очк.';
  s.canUndo=true;
 }
}
return {state:s};
